DRIVER=''
import base64,hashlib,json,os,shutil,struct,subprocess,time,uuid,wave
from pathlib import Path
b=Path('${BUILD_ROOT}')
image='sha256:a3f63d1003795b29af6e512fde6a3f37c7942b986d7a57e4fe4fd9f32c204d9e'
public=b/'target/dictation-preview-context-public-vv0volrg'
e=json.loads((public/'public-receipt.json').read_text())
assert e['revision']=='70bb2e84b976b7e960aa89f1c648e09c59f894dd'
assert [c['id'] for c in e['cases']]==['fr_fr-0','en_us-0','de_de-0']
model=Path('${PUBLIC_MODEL_ROOT}/small-q5_1.bin')
assert model.stat().st_size==190085487 and hashlib.file_digest(model.open('rb'),'sha256').hexdigest()=='ae85e4a935d7a567bd102fe55afc16bb595bdb618e11b2fc7591bc08120411bb'
source=b/'src/crates/agent/local-model-service/native'
bridge=(source/'speech.cpp').read_text()
assert hashlib.sha256(bridge.encode()).hexdigest()=='9062e7d150e8dc39666e50a53ab91e08ab7ea4a8b7440af284d3d151c2b9f7e3'
up=source/'upstream/whisper.cpp'
assert hashlib.file_digest((up/'include/whisper.h').open('rb'),'sha256').hexdigest()=='0525b758571ab71c00ddd8ea2845f74af7c62dfa5100c5586655f75bdc5ef4be'
paths=sorted((b/'target/debug/build').glob('local-model-service-*/out/speech-install/lib/libwhisper.a'))
assert paths and len({hashlib.file_digest(p.open('rb'),'sha256').hexdigest() for p in paths})==1
libs=paths[0].parent
out=b/'target/dictation-preview-context-r3'
assert not out.exists();out.mkdir(mode=0o755)
(out/'driver.cpp').write_bytes(base64.b64decode(DRIVER))
old='uint8_t * output, size_t capacity) noexcept try {'
assert bridge.count(old)==1
bridge=bridge.replace('tilo_speech_transcribe(', 'tilo_speech_transcribe_context(').replace(old,'uint8_t * output, size_t capacity, int audio_ctx) noexcept try {')
needle='    params.no_context = true;'
assert bridge.count(needle)==1
bridge=bridge.replace(needle,needle+'\n    if (audio_ctx < 0 || audio_ctx > whisper_n_audio_ctx(ctx) ||\n        (audio_ctx > 0 && (count + 319) / 320 + 100 > audio_ctx)) return -7;\n    params.audio_ctx = audio_ctx;')
(out/'bridge.cpp').write_text(bridge)
(out/'limit.py').write_text("import os,resource,sys\nresource.setrlimit(resource.RLIMIT_AS,(1073741824,1073741824))\nresource.setrlimit(resource.RLIMIT_CORE,(0,0))\nos.execv(sys.argv[1],sys.argv[1:])\n")
for c in e['cases']:
 p=public/c['file'];assert p.stat().st_size==c['size'] and hashlib.file_digest(p.open('rb'),'sha256').hexdigest()==c['sha256']
 with wave.open(str(p)) as audio:
  assert (audio.getnchannels(),audio.getsampwidth(),audio.getframerate(),audio.getcomptype())==(1,2,16000,'NONE')
  pcm=audio.readframes(audio.getnframes())
 (out/(c['id']+'.f32')).write_bytes(b''.join(struct.pack('<f',v[0]/32768.0) for v in struct.iter_unpack('<h',pcm)))
for p in out.iterdir():p.chmod(0o644)
compile_name='dictation-preview-compile-'+uuid.uuid4().hex[:12]
compile_command=['podman','run','--rm','--name',compile_name,'--network=none','--cap-drop=ALL','--security-opt=no-new-privileges','--security-opt=label=disable','--read-only','--tmpfs','/tmp:rw,nosuid,nodev,size=128m','--cpus=2','--memory=512m','--memory-swap=512m','--pids-limit=64','-v',str(out)+':/review:rw','-v',str(up)+':/upstream:ro','-v',str(libs)+':/libs:ro',image,'c++','-std=c++17','-O2','-Wall','-Wextra','-Werror','-I/upstream/include','-I/upstream/ggml/include','/review/driver.cpp','/review/bridge.cpp',*[str(Path('/libs')/name) for name in ['libwhisper.a','libggml.a','libggml-cpu.a','libggml-base.a']],'-lpthread','-ldl','-o','/review/driver']
try:
 result=subprocess.run(compile_command,capture_output=True,text=True,timeout=120)
finally:
 if subprocess.run(['podman','container','exists',compile_name],capture_output=True).returncode==0:
  subprocess.run(['podman','stop','--time','2',compile_name],capture_output=True,timeout=15)
 assert subprocess.run(['podman','container','exists',compile_name],capture_output=True).returncode==1
(out/'compile.log').write_text(result.stdout+result.stderr)
assert result.returncode==0,result.stderr[-3000:]
assert subprocess.run(['podman','container','exists',compile_name],capture_output=True).returncode==1
(out/'driver').chmod(0o755)
receipt={'source_head':json.loads((b/'meta.json').read_text())['head'],'bridge_source_sha256':'9062e7d150e8dc39666e50a53ab91e08ab7ea4a8b7440af284d3d151c2b9f7e3','private_review_only':True,'production_policy_changed':False,'context_guard':'ceil(samples/320)+100<=context; negative/outgrown/above-model context refuses; final is decoded at0','limits':{'CPUs':2,'address_space_bytes':1073741824,'container_memory_bytes':1073741824,'PID_limit':64,'network':False,'hardware_mounts':False},'public_cases':e,'compiled_files':{p.name:hashlib.file_digest(p.open('rb'),'sha256').hexdigest() for p in out.iterdir() if p.is_file()},'native_libraries':{p.name:hashlib.file_digest(p.open('rb'),'sha256').hexdigest() for p in libs.glob('lib*.a')},'runs':[]}
for c in e['cases']:
 name='dictation-preview-case-'+uuid.uuid4().hex[:12]
 command=['podman','run','--rm','--name',name,'--network=none','--cap-drop=ALL','--security-opt=no-new-privileges','--security-opt=label=disable','--read-only','--user=65534:65534','--cpus=2','--memory=1g','--memory-swap=1g','--pids-limit=64','--ulimit','core=0:0','-v',str(out)+':/review:ro','-v',str(model)+':/model:ro',image,'python3','/review/limit.py','/review/driver','/model','/review/'+c['id']+'.f32',c['language']]
 before=time.monotonic()
 try:run=subprocess.run(command,capture_output=True,text=True,timeout=180)
 finally:
  if subprocess.run(['podman','container','exists',name],capture_output=True).returncode==0:
   subprocess.run(['podman','stop','--time','2',name],capture_output=True,timeout=15)
  assert subprocess.run(['podman','container','exists',name],capture_output=True).returncode==1
 log=out/(c['id']+'.log');log.write_text(run.stdout+run.stderr)
 assert subprocess.run(['podman','container','exists',name],capture_output=True).returncode==1
 row={'case':c['id'],'exit':run.returncode,'command':command,'seconds':time.monotonic()-before,'owned_container_verified_absent':name,'log_sha256':hashlib.file_digest(log.open('rb'),'sha256').hexdigest()}
 receipt['runs'].append(row);print('PREVIEW_RUN',json.dumps(row),flush=True)
 if run.returncode:break
receipt['complete']=len(receipt['runs'])==3 and all(r['exit']==0 for r in receipt['runs'])
(out/'receipt.json').write_text(json.dumps(receipt,indent=2)+'\n')
for p in sorted(out.iterdir()):
 if p.suffix in ['.log','.json','.cpp','.py']:print('PREVIEW_EXPORT',json.dumps({'name':p.name,'sha256':hashlib.file_digest(p.open('rb'),'sha256').hexdigest(),'base64':base64.b64encode(p.read_bytes()).decode()}),flush=True)
print('PREVIEW_EXPERIMENT_COMPLETE',receipt['complete'],flush=True)
